import{_ as p,a0 as o,w as r,s as d,ao as i,I as l,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何解決 “mount.nfs: Stale file handle”錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"如何解決 “mount.nfs: Stale file handle”錯誤 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解決 “mount.nfs: Stale file handle”錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解決 “mount.nfs: Stale file handle”錯誤 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20170101 How to resolve mount.nfs- Stale file handle error","title":"如何解決 “mount.nfs: Stale file handle”錯誤","tag":"201804","desc":""},"relativePath":"201804/20170101 How to resolve mount.nfs- Stale file handle error.md","filePath":"[post].md"}'),u={name:"201804/20170101 How to resolve mount.nfs- Stale file handle error.md"};function f(m,s,h,g,k,S){const a=o("Link");return r(),d("div",null,[s[21]||(s[21]=i(`<h1 id="如何解決-mount-nfs-stale-file-handle-錯誤" tabindex="-1">如何解決 “mount.nfs: Stale file handle”錯誤 <a class="header-anchor" href="#如何解決-mount-nfs-stale-file-handle-錯誤" aria-label="Permalink to “如何解決 “mount.nfs: Stale file handle”錯誤”">​</a></h1><blockquote><p>瞭解如何解決 Linux 平台上的 <code>mount.nfs: Stale file handle</code> 錯誤。這個 NFS 錯誤可以在客户端或者服務端解決。</p></blockquote><p><em><img src="http://kerneltalks.com/wp-content/uploads/2017/01/nfs_error-2-150x150.png" alt=""></em></p><p>當你在你的環境中使用網絡文件系統時，你一定不時看到 <code>mount.nfs：Stale file handle</code> 錯誤。此錯誤表示 NFS 共享無法掛載，因為自上次配置後有些東西已經更改。</p><p>無論是你重啓 NFS 服務器或某些 NFS 進程未在客户端或服務器上運行，或者共享未在服務器上正確輸出，這些都可能是導致這個錯誤的原因。此外，當這個錯誤發生在先前掛載的 NFS 共享上時，它會令人不快。因為這意味着配置部分是正確的，因為是以前掛載的。在這種情況下，可以嘗試下面的命令：</p><p>確保 NFS 服務在客户端和服務器上運行良好。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#  service nfs status</span></span>
<span class="line"><span>rpc.svcgssd is stopped</span></span>
<span class="line"><span>rpc.mountd (pid 11993) is running...</span></span>
<span class="line"><span>nfsd (pid 12009 12008 12007 12006 12005 12004 12003 12002) is running...</span></span>
<span class="line"><span>rpc.rquotad (pid 11988) is running...</span></span></code></pre></div><p>如果 NFS 共享目前掛載在客户端上，則強制卸載它並嘗試在 NFS 客户端上重新掛載它。通過 <code>df</code> 命令檢查它是否正確掛載，並更改其中的目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># umount -f /mydata_nfs</span></span>
<span class="line"><span> </span></span>
<span class="line"><span># mount -t nfs server:/nfs_share /mydata_nfs</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>#df -k</span></span>
<span class="line"><span>------ output clipped -----</span></span>
<span class="line"><span>server:/nfs_share 41943040  892928  41050112   3% /mydata_nfs</span></span></code></pre></div>`,9)),l("p",null,[s[1]||(s[1]=n("在上面的掛載命令中，服務器可以是 NFS 服務器的 IP 或",-1)),e(a,{href:"https://kerneltalks.com/linux/all-you-need-to-know-about-hostname-in-linux/"},{default:t(()=>[...s[0]||(s[0]=[n("主機名",-1)])]),_:1}),s[2]||(s[2]=n("。",-1))]),s[22]||(s[22]=i(`<p>如果你在強制取消掛載時遇到像下面錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># umount -f /mydata_nfs</span></span>
<span class="line"><span>umount2: Device or resource busy</span></span>
<span class="line"><span>umount: /mydata_nfs: device is busy</span></span>
<span class="line"><span>umount2: Device or resource busy</span></span>
<span class="line"><span>umount: /mydata_nfs: device is busy</span></span></code></pre></div><p>然後你可以用 <code>lsof</code> 命令來檢查哪個進程或用户正在使用該掛載點，如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># lsof |grep mydata_nfs</span></span>
<span class="line"><span>lsof: WARNING: can&#39;t stat() nfs file system /mydata_nfs</span></span>
<span class="line"><span>      Output information may be incomplete.</span></span>
<span class="line"><span>su         3327      root  cwd   unknown                                                   /mydata_nfs/dir (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash       3484      grid  cwd   unknown                                                   /mydata_nfs/MYDB (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash      20092  oracle11  cwd   unknown                                                   /mydata_nfs/MPRP (stat: Stale NFS file handle)</span></span>
<span class="line"><span>bash      25040  oracle11  cwd   unknown                                                   /mydata_nfs/MUYR (stat: Stale NFS file handle)</span></span></code></pre></div><p>如果你在上面的示例中看到共有 4 個 PID 正在使用該掛載點上的某些文件。嘗試殺死它們以釋放掛載點。完成後，你將能夠正確卸載它。</p><p>有時 <code>mount</code> 命令會有相同的錯誤。接着使用下面的命令在客户端重啓 NFS 服務後掛載。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#  service nfs restart</span></span>
<span class="line"><span>Shutting down NFS daemon:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down NFS mountd:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down NFS quotas:                                  [  OK  ]</span></span>
<span class="line"><span>Shutting down RPC idmapd:                                  [  OK  ]</span></span>
<span class="line"><span>Starting NFS services:                                     [  OK  ]</span></span>
<span class="line"><span>Starting NFS quotas:                                       [  OK  ]</span></span>
<span class="line"><span>Starting NFS mountd:                                       [  OK  ]</span></span>
<span class="line"><span>Starting NFS daemon:                                       [  OK  ]</span></span></code></pre></div>`,7)),l("p",null,[s[4]||(s[4]=n("另請閲讀：",-1)),e(a,{href:"http://kerneltalks.com/hpux/restart-nfs-in-hpux/"},{default:t(()=>[...s[3]||(s[3]=[n("如何在 HPUX 中逐步重啓 NFS",-1)])]),_:1})]),l("p",null,[s[6]||(s[6]=n("即使這沒有解決你的問題，最後一步是在 NFS 服務器上重啓服務。警告！這將斷開從該 NFS 服務器輸出的所有 NFS 共享。所有客户端將看到掛載點斷開。這一步將 99％ 解決你的問題。如果沒有，請務必檢查 ",-1)),e(a,{href:"http://kerneltalks.com/linux/nfs-configuration-linux-hpux/"},{default:t(()=>[...s[5]||(s[5]=[n("NFS 配置",-1)])]),_:1}),s[7]||(s[7]=n("，提供你修改的配置併發布你啓動時看到的錯誤。",-1))]),s[23]||(s[23]=l("p",null,"上面文章中的輸出來自 RHEL6.3 服務器。請將你的評論發送給我們。",-1)),s[24]||(s[24]=l("hr",null,null,-1)),l("p",null,[s[9]||(s[9]=n("via: ",-1)),e(a,{href:"https://kerneltalks.com/troubleshooting/resolve-mount-nfs-stale-file-handle-error/"},{default:t(()=>[...s[8]||(s[8]=[n("https://kerneltalks.com/troubleshooting/resolve-mount-nfs-stale-file-handle-error/",-1)])]),_:1})]),l("p",null,[s[13]||(s[13]=n("作者：",-1)),e(a,{href:"https://kerneltalks.com"},{default:t(()=>[...s[10]||(s[10]=[n("KernelTalks",-1)])]),_:1}),s[14]||(s[14]=n(" 譯者：",-1)),e(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[11]||(s[11]=[n("geekpi",-1)])]),_:1}),s[15]||(s[15]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[12]||(s[12]=[n("wxy",-1)])]),_:1})]),l("p",null,[s[18]||(s[18]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[16]||(s[16]=[n("LCTT",-1)])]),_:1}),s[19]||(s[19]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[17]||(s[17]=[n("Linux中國",-1)])]),_:1}),s[20]||(s[20]=n(" 榮譽推出",-1))])])}const N=p(u,[["render",f]]);export{y as __pageData,N as default};
